import {MORE_SCENES} from './continuation-scenes.e518df4e9bd6.js';
import {bigram,vocabulary,rnn,lstm,gru,crossAttention,selfAttention,attentionX,WQ,WK,WV,softmax,fmt} from './math.e518df4e9bd6.js';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const A=(at,html,until=99)=>`<g class="atom" data-at="${at}" data-until="${until}">${html}</g>`;
function text(x,y,s,cls='',anchor='middle'){const lines=String(s).split('\n'),dy=cls.includes('small')?27:34;return `<text x="${x}" y="${y-(lines.length-1)*dy/2}" text-anchor="${anchor}" class="svgtxt ${cls}">${lines.map((l,i)=>`<tspan x="${x}" dy="${i?dy:0}">${esc(l)}</tspan>`).join('')}</text>`;}
const box=(x,y,w,h,s,k=0,style='')=>A(k,`<rect class="node ${style}" x="${x}" y="${y}" width="${w}" height="${h}" rx="7"/>${text(x+w/2,y+h/2+8,s,(style.includes('dark')?'white ':'')+(String(s).split('\n').some(l=>l.length*14>w-24)?'small':''))}`);
const line=(x1,y1,x2,y2,k=0,cls='')=>A(k,`<path class="edge ${cls}" d="M${x1},${y1} L${x2},${y2}"/>`);
const path=(d,k=0,cls='')=>A(k,`<path class="edge ${cls}" d="${d}"/>`);
const op=(x,y,s,k=0)=>A(k,`<circle class="op" cx="${x}" cy="${y}" r="25"/>${text(x,y+9,s)}`);
const wrap=s=>`<svg viewBox="0 0 1380 520" role="img" aria-label="Animated architecture diagram"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#64748b"/></marker></defs>${s}</svg>`;
function matrix(x,y,m,label,at=0,{cell=58,dec=2,color=false}={}){let s=text(x+m[0].length*cell/2,y-23,label,'small bold');for(let i=0;i<m.length;i++)for(let j=0;j<m[i].length;j++){const v=m[i][j],fill=color?`rgba(79,109,154,${.08+.82*(Number.isFinite(v)?v:0)})`:'#edf2f7';s+=`<rect class="matrix-cell" x="${x+j*cell}" y="${y+i*cell}" width="${cell}" height="${cell}" fill="${fill}"/>${text(x+(j+.5)*cell,y+(i+.5)*cell+7,typeof v==='number'?(Number.isFinite(v)?fmt(v,dec):'−∞'):v,'small')}`;}return A(at,s);}
function chain(labels,{x=35,y=220,w=225,h=90,gap=60,start=1}={}){return labels.map((s,i)=>box(x+i*(w+gap),y,w,h,s,start+i)+(i?line(x+(i-1)*(w+gap)+w,y+h/2,x+i*(w+gap),y+h/2,start+i):'')).join('');}
export const SCENES={
'chain-rule':state=>({svg:wrap(box(25,35,1330,75,'I   like   language   models',0,'data')+chain(['P(I)','P(like | I)','P(language | I like)','P(models | I like language)'],{x:10,y:215,w:295,gap:50})+A(5,text(690,410,'Multiply the conditional probabilities to score the sequence','bold'))),caps:['A language model gives a probability to each next token.','First token: P(I).','Second token: condition on the first token.','Third token: condition on the whole prefix.','Fourth token: the prefix keeps growing.','The chain rule is exact. Approximations enter when we choose a model.']}),
'ngram-window':state=>{const n=Number(state.n||2),words=['The','keys','to','the','cabinet','are'],start=Math.max(0,5-(n-1));return {svg:wrap(words.map((w,i)=>box(20+i*225,170,205,85,w,0,i===5?'dark':i>=start?'data':'')).join('')+A(1,`<path d="M${20+start*225},300 H${20+4*225+205}" stroke="#4f6d9a" stroke-width="5"/>`)+A(1,text(690,375,`${n}-gram: only ${n-1} previous token${n===2?'':'s'} remain visible`,'bold'))+A(2,text(690,460,n<6?'The subject “keys” is outside this context window.':'The window now includes the subject “keys”.','small'))),controls:[{type:'select',key:'n',label:'Order n',options:[['2','Bigram'],['3','Trigram'],['6','6-gram']]}],caps:['The correct verb is “are”; the plural subject is “keys”.','The Markov assumption keeps only the last n − 1 tokens.','Increasing n can restore this dependency, but creates more possible contexts.']};},
'counts':state=>{let d=bigram(state.context||'I',0);return {svg:wrap(box(40,30,490,180,'I like NLP\nI like deep learning\nI study NLP',0,'data')+line(530,120,670,120,1)+box(670,55,650,120,`Context: ${state.context||'I'}`,1)+d.map((r,i)=>A(2,text(100+i*190,300,r.word,'small')+text(100+i*190,355,`count ${r.count}`,'small')+text(100+i*190,425,`P = ${fmt(r.p,2)}`,'bold'))).join('')),controls:[{type:'select',key:'context',label:'Previous word',options:['I','like','NLP','<s>']}],caps:['Our entire training corpus has three short sentences. Start and end markers are included when counting.','Choose a context. We count the words that follow it.','Divide each count by the total number of outgoing transitions. These probabilities are computed from the corpus.']};},
'smoothing':state=>{let alpha=Number(state.alpha??1),d=bigram('like',alpha);return {svg:wrap(A(0,text(690,45,`Context “like”: NLP = 1, deep = 1, all other counts = 0`,'bold'))+d.map((r,i)=>A(1,`<rect x="${40+i*190}" y="${345-r.p*310}" width="115" height="${r.p*310}" fill="${r.word==='learning'?'#8b614a':'#4f6d9a'}"/>`+text(97+i*190,390,r.word,'small')+text(97+i*190,440,fmt(r.p,3),'small'))).join('')+A(2,text(690,505,`α = ${alpha}: sum of probabilities = ${fmt(d.reduce((s,r)=>s+r.p,0),3)}`,'small bold'))),controls:[{type:'range',key:'alpha',label:'Add-α',min:0,max:1,step:.1,value:1}],caps:['An unseen transition gets zero probability under maximum likelihood.','Add α to every count and add αV to the denominator. Move the slider to see the redistribution.','The distribution stays normalised. Smoothing gives unseen transitions probability, but does not learn word similarity.']};},
'neural-lm':state=>({svg:wrap(['the','cat','sat'].map((s,i)=>box(85+i*460,400,280,70,s,0,'data')+box(85+i*460,270,280,75,`embedding e${i+1} ∈ Rᵈ`,1)+line(225+i*460,400,225+i*460,345,1)).join('')+box(390,130,600,80,'Concatenate → hidden layer',2)+[225,685,1145].map(x=>path(`M${x},270 V235 H690 V210`,2)).join('')+box(490,5,400,75,'Softmax → next-token distribution',3)+line(690,130,690,80,3)),caps:['A fixed-window neural model uses the last few tokens as input.','Look up a learned vector for each token. The same embedding table serves all positions.','Concatenate the vectors, then apply a learned hidden transformation.','Project to vocabulary logits and apply softmax. Similar contexts can share statistical strength.']}),
'rnn-cell':state=>({svg:wrap(box(20,90,250,90,'hₜ₋₁ ∈ Rᵈʰ',0,'data')+box(20,350,250,90,'xₜ ∈ Rᵈˣ',0,'data')+box(410,205,300,110,'Wₕhₜ₋₁ + Wₓxₜ + b',1)+path('M270,135 H340 V245 H410',1)+path('M270,395 H340 V280 H410',1)+box(830,205,190,110,'tanh',2)+line(710,260,830,260,2)+box(1130,205,240,110,'hₜ ∈ Rᵈʰ',3,'data')+line(1020,260,1130,260,3)+box(1070,15,300,90,'Linear + softmax\nnext-token distribution',4)+line(1250,205,1250,105,4)),caps:['The cell receives the current input and the previous hidden state.','Two learned projections add information from the token and the past.','The nonlinearity produces a new representation.','This new hidden state becomes the memory for the next time step.','An output head maps the hidden state to next-token probabilities.']}),
'rnn-unroll':state=>{const rs=rnn();let s='';rs.forEach((r,i)=>{let x=130+i*440;s+=box(x,215,260,100,`RNN cell\nh${i+1} = ${fmt(r.h)}`,i+1)+box(x+25,395,210,65,`x${i+1} = ${r.x}`,i+1,'data')+line(x+130,395,x+130,315,i+1)+box(x+10,20,240,95,'Linear + softmax',i+2)+line(x+130,215,x+130,115,i+2);if(i)s+=line(x-180,265,x,265,i+1);});s+=box(0,225,100,80,'h₀ = 0',0,'data')+line(100,265,130,265,1);return {svg:wrap(s),caps:['One cell can be reused at every position. Toy scalar RNN: hₜ = tanh(0.6xₜ + 0.8hₜ₋₁).','Read x₁ = 1. The new state is tanh(0.6).','Read x₂ = 0.5. Combine the token with the previous state.','Read x₃ = −1. Its new evidence changes the memory.','Each hidden state can predict the next token. All cells share parameters.']};},
'rnn-numeric':state=>{const rs=rnn();return {svg:wrap(rs.map((r,i)=>{const x=45+i*460;return box(x,40,390,90,`x${i+1} = ${r.x}   h${i} = ${fmt(r.prev)}`,i)+line(x+195,130,x+195,210,i+1)+box(x,210,390,110,`0.6x + 0.8h = ${fmt(r.pre)}`,i+1)+line(x+195,320,x+195,395,i+1)+box(x,395,390,75,`tanh → ${fmt(r.h)}`,i+1,'data');}).join('')),caps:['Start from h₀ = 0; every step uses the same two scalar weights.','Step 1: tanh(0.6) = '+fmt(rs[0].h)+'.','Step 2 includes both new evidence and the previous state.','Step 3 changes the sign. This is exact arithmetic for our tiny RNN, not a pretrained-model prediction.']};},
'gradient':state=>{const f=Number(state.factor??.5),vals=Array.from({length:6},(_,i)=>f**(i*4));return {svg:wrap(vals.map((v,i)=>{const x=50+i*220;return box(x,210,180,75,`h${20-i*4}`,0,'data')+(i?line(x-40,250,x,250,i):'')+A(i,text(x+90,155,`${fmt(v,v<.001?6:3)}`,'bold'));}).join('')+A(5,text(690,410,`20-step multiplier: ${f}²⁰ = ${(f**20).toExponential(3)}`,'bold'))),controls:[{type:'select',key:'factor',label:'Toy local derivative',options:[['0.5','0.5 · vanishing'],['1','1.0 · preserved'],['1.5','1.5 · exploding']]}],caps:['Read the path backwards from the final loss. These are scalar teaching factors, not measured gradient norms.','Four recurrent steps multiply the signal by another factor⁴.','Long products can shrink or amplify the learning signal.','Early inputs may receive very little useful gradient.','Real RNNs multiply Jacobian matrices, including weight matrices and activation derivatives.','Gradient clipping limits explosion. Gated memory paths can improve gradient flow, without guaranteeing it.']};},
'lstm':state=>{const q=lstm(Number(state.f??.9));let s=box(0,65,190,75,`cₜ₋₁\n${fmt(q.prev)}`,0,'data')+op(410,103,'×',2)+op(855,103,'+',4)+box(1130,65,235,75,`cₜ = ${fmt(q.c)}`,4,'data')+line(190,103,385,103,2,'thick')+line(435,103,830,103,3,'thick')+line(880,103,1130,103,4,'thick')+box(280,265,260,80,`Forget f = ${fmt(q.f,2)}`,1)+line(410,265,410,128,2)+box(630,265,210,80,`Input i = ${q.i}`,3)+box(900,265,220,80,`Candidate g = ${q.g}`,3)+op(855,210,'×',3)+path('M735,265 V210 H830',3)+path('M1010,265 V210 H880',3)+line(855,185,855,128,4)+box(55,420,520,70,'[hₜ₋₁ ; xₜ] → learned gate projections',0,'data')+box(1130,265,235,80,`o = ${q.o}; tanh(cₜ)`,5)+line(1247,140,1247,265,5)+box(1130,420,235,70,`hₜ = ${fmt(q.h)}`,6,'dark')+line(1247,345,1247,420,6)+A(2,text(640,65,`keep = f ⊙ cₜ₋₁ = ${fmt(q.keep)}`,'small'))+A(3,text(840,385,`write = i ⊙ g = ${fmt(q.write)}`,'small'));return {svg:wrap(s),controls:[{type:'range',key:'f',label:'Forget gate f',min:.05,max:.95,step:.05,value:.9}],caps:['Two states enter: previous cell memory c and previous visible state h. Inputs feed all gates.','A sigmoid gate produces f between 0 and 1, separately for each memory coordinate.','Multiply old memory by f. Here, '+fmt(q.keep)+' survives.','The input gate scales a candidate update; this example writes −0.100.','Add retained memory and new information: cₜ = '+fmt(q.c)+'.','Apply tanh to the cell state; the output gate selects what becomes visible.','hₜ = o ⊙ tanh(cₜ) = '+fmt(q.h)+'. Move f to see how the carry path changes.']};},
'gru':state=>{let q=gru(Number(state.z??.25),Number(state.r??.3));return {svg:wrap(box(20,40,230,85,`hₜ₋₁ = ${q.prev}`,0,'data')+box(20,400,230,70,`xₜ = ${q.x}`,0,'data')+box(380,40,300,80,`Keep: 1 − z = ${fmt(1-q.z,2)}`,1)+line(250,80,380,80,1)+box(380,300,300,80,`Reset r = ${fmt(q.r,2)}`,2)+path('M250,80 H305 V340 H380',2)+box(800,295,300,90,`Candidate h̃ = ${fmt(q.candidate)}`,3)+line(680,340,800,340,3)+path('M250,435 H740 V365 H800',3)+box(800,40,300,80,`Old part = ${fmt(q.keep)}`,4)+line(680,80,800,80,4)+op(1200,235,'+',5)+path('M1100,80 H1200 V210',5)+path('M1100,340 H1200 V260',5)+box(1110,400,250,80,`hₜ = ${fmt(q.h)}`,5,'dark')+line(1200,260,1200,400,5)+A(3,text(950,435,`New part z·h̃ = ${fmt(q.write)}`,'small'))+A(2,text(690,210,`r·hₜ₋₁ = ${fmt(q.reset)}`,'small'))),controls:[{type:'range',key:'z',label:'New fraction z',min:0,max:1,step:.05,value:.25},{type:'range',key:'r',label:'Reset r',min:0,max:1,step:.05,value:.3}],caps:['A GRU has one hidden state; no separate cell state. Toy weights: candidate = tanh(0.6x + 0.8(rh)).','Our convention: z is the fraction assigned to the new candidate. Other sources may reverse z.','The reset gate changes how the old state contributes to the candidate.','Combine the current input with the reset version of the old state.','The direct carry path contributes (1 − z)hₜ₋₁.','Add old and new parts. Changing r affects the candidate, not the direct carry path.']};},
'seq2seq':state=>{const training=state.mode!=='generation';let s='';['the','red','car'].forEach((w,i)=>{let x=30+i*230;s+=box(x,235,180,85,'Encoder',i+1)+box(x,380,180,65,w,i+1,'data')+line(x+90,380,x+90,320,i+1)+(i?line(x-50,275,x,275,i+1):'');});s+=box(750,235,250,85,'Context c',4,'data')+line(670,275,750,275,4)+box(1080,235,270,85,'Decoder',5)+line(1000,275,1080,275,5);['la','voiture','rouge','</s>'].forEach((w,i)=>{s+=box(760+i*150,40,140,70,w,6+i,i===3?'dark':'data');});s+=path('M1215,235 V155 H1110 V110',6)+box(1050,405,310,70,training?'Previous gold token':'Previous generated token',5,'data')+line(1200,405,1200,320,5)+(training?'':path('M1215,155 H1370 V440 H1360',7));return {svg:wrap(s),controls:[{type:'select',key:'mode',label:'Decoder input',options:[['training','Training · gold prefix'],['generation','Generation · own prefix']]}],caps:['The source has three words; the target can have a different order or length.','Read “the”.','Read “red”.','Read “car”. Encoder weights are shared across source positions.','The final state initialises or conditions a separate decoder.','Begin with a start token; the decoder has its own recurrent state.','Predict “la”. This fixed translation is an illustration, not a model prediction.','Predict “voiture”. '+(training?'Teacher forcing supplies the true previous target.':'Generation feeds back the model’s previous output.'),'Predict “rouge”: adjective position changes.','Stop after the end token. The output length is not tied to source length.']};},
'bottleneck':state=>{let long=state.length==='40';return {svg:wrap(box(25,170,530,100,long?'The committee that reviewed …\n40 input words':'Transformers are great !\n4 input words',0,'data')+line(555,220,690,220,1)+box(690,140,250,170,'One context vector\n512 values',1)+line(940,220,1070,220,2)+box(1070,170,280,100,'Decoder',2)+A(3,text(690,400,'The representation dimension stays fixed as the source grows','bold'))+A(3,text(690,460,'This is a practical capacity bottleneck—not a literal equal allocation of values per word.','small'))),controls:[{type:'select',key:'length',label:'Input length',options:[['4','4 words'],['40','40 words']]}],caps:['Choose a short or long source.','The encoder still hands over a fixed-dimensional representation.','Without attention, the decoder has no direct route back to each source state.','Long inputs can make this bottleneck harder. A fixed vector does not guarantee loss, but the learning problem becomes difficult.']};},
'cross-attention':state=>{const q=crossAttention(state.query==='swap'?[2,1]:[1,2]);let s='';['I','love','NLP'].forEach((w,i)=>{let x=55+i*360;s+=box(x,390,250,75,`${w}: h${i+1} = [${i===0?'1,0':i===1?'0,1':'1,1'}]`,0,'data')+A(2,text(x+125,330,`score ${q.scores[i]}`,'small'))+A(3,text(x+125,265,`α${i+1} = ${fmt(q.weights[i])}`,'bold'))+path(`M${x+125},390 V220 H690 V185`,4);});s+=box(1060,50,290,100,`query s = [${q.q}]`,1,'data')+box(450,90,480,95,`context = [${q.context.map(x=>fmt(x)).join(', ')}]`,4)+line(1060,100,930,135,2);return {svg:wrap(s),controls:[{type:'select',key:'query',label:'Toy decoder query',options:[['normal','s = [1, 2]'],['swap','s = [2, 1]']]}],caps:['Keep one encoder state for each source token. These two-dimensional states are chosen for teaching.','The current decoder state asks a query about the source.','For easy arithmetic, this example uses dot-product scores. Original Bahdanau attention uses an additive scoring network.','Softmax makes positive weights that sum to one.','The context is a weighted sum of source states. Change the query to recompute the allocation.']};},
'alignment':state=>{let scores=[[3,0,0],[.2,.1,3],[.1,3,.2]],weights=scores.map(softmax),s=weights.map((row,i)=>matrix(370,90+i*110,[row],'',i+1,{cell:110,dec:2,color:true})).join('')+A(1,text(1030,80,'Computed soft alignments','small bold'));['the','red','car'].forEach((w,i)=>s+=A(0,text(425+i*110,55,w,'small')));['la','voiture','rouge'].forEach((w,i)=>s+=A(i+1,text(290,150+i*110,w,'small','end')));s+=A(4,text(1000,210,'Output order can differ\nfrom source order','bold'))+A(4,text(690,490,'Chosen teaching scores; row softmax produces the displayed values.','small'));return {svg:wrap(s),caps:['Columns are source words. Rows are target positions.','For “la”, the strongest weight is on “the”.','For “voiture”, focus shifts to “car”.','For “rouge”, focus shifts back to “red”.','Attention offers flexible soft alignment. A weight is a routing coefficient, not a complete explanation of a prediction.']};},
'parallel':state=>({svg:wrap(A(0,text(35,80,'Recurrent encoding','bold','start'))+Array.from({length:5},(_,i)=>box(30+i*275,130,210,80,`h${i+1}`,i+1,'data')+(i?line(30+(i-1)*275+210,170,30+i*275,170,i+1):'')).join('')+A(0,text(35,315,'Self-attention layer','bold','start'))+Array.from({length:5},(_,i)=>box(30+i*275,365,210,80,`position ${i+1}`,6,'data')).join('')+A(7,text(690,510,'Parallel positions during training; generated future tokens are still unknown.','small bold'))),caps:['Compare dependencies within one layer, rather than parameter count.','RNN position 1 must finish first.','Position 2 uses position 1.','Position 3 waits again.','The dependency chain grows with sequence length.','The last recurrent state depends on every earlier computation.','A self-attention layer can compute all known input positions together.','Autoregressive generation still needs the previous output before predicting the next.']}),
'qkv':state=>{const a=selfAttention();return {svg:wrap(matrix(30,180,attentionX,'X · 3 × 2',0)+box(300,55,260,75,'WQ = identity',1)+box(300,220,260,75,'WK = [[1,1],[0,1]]',2)+box(300,385,260,75,'WV = [[1,0],[0,2]]',3)+path('M205,267 H250 V92 H300',1)+line(205,267,300,257,2)+path('M205,267 H250 V422 H300',3)+matrix(650,60,a.Q,'Q = XWQ',1)+matrix(900,180,a.K,'K = XWK',2)+matrix(1150,345,a.V,'V = XWV',3)),caps:['Rows are token representations. These are tiny chosen matrices, not learned embeddings.','Queries encode what each position is looking for.','Keys encode how each source position can be matched.','Values carry the information that attention will mix. The three projection matrices serve different roles.']};},
'attention-math':state=>{const a=selfAttention(state.mask==='causal'),i=Number(state.row||0),weights=a.weights[i],s=matrix(25,130,[a.Q[i]],`q${i+1}`,0)+matrix(240,80,a.K,'K',1)+matrix(530,130,[a.scores[i].map((v,j)=>state.mask==='causal'&&j>i?-Infinity:v)],'scaled + masked scores',2)+matrix(790,130,[weights],'softmax weights',3,{color:true})+matrix(1110,240,[a.out[i]],'weighted values',4)+A(4,text(800,430,`z${i+1} = ${weights.map((w,j)=>`${fmt(w,2)}·v${j+1}`).join(' + ')}`,'small'))+A(2,text(700,40,state.mask==='causal'?'Future-position scores are replaced by −∞ before softmax.':'All input positions are available in this encoder-style example.','small'));return {svg:wrap(s),controls:[{type:'select',key:'row',label:'Query row',options:[['0','Token 1'],['1','Token 2'],['2','Token 3']]},{type:'select',key:'mask',label:'Visibility',options:[['full','Bidirectional'],['causal','Causal']]}],caps:['Select one query row from Q.','Compare that query with every key vector.','Divide dot products by √dₖ. A causal mask removes access to future keys.','Softmax converts the permitted scores into a probability distribution.','Multiply those weights by V. This is the exact output of this tiny attention head.']};},
'mask':state=>{const causal=state.mask!=='full',m=Array.from({length:5},(_,i)=>Array.from({length:5},(_,j)=>causal&&j>i?'×':'✓'));return {svg:wrap(matrix(300,70,m,'Rows: queries · columns: keys',1,{cell:77,dec:0})+A(0,text(980,160,causal?'Causal self-attention':'Bidirectional self-attention','bold'))+A(2,text(1010,275,causal?'Position 3 can use\npositions 1, 2 and 3':'Each token can use\nall known input positions','small'))+A(3,text(690,505,causal?'Targets are shifted. The model cannot inspect the token it must predict.':'A masked-language objective hides selected input tokens; the remaining context can be bidirectional.','small'))),controls:[{type:'select',key:'mask',label:'Attention mask',options:[['causal','Causal'],['full','Bidirectional']]}],caps:['The mask defines which query–key pairs are allowed.','Allowed connections remain visible; blocked connections get −∞ in the score matrix.','A causal row includes its own input position, but not future positions.','For next-token training, the prediction target is the next position—not the token already in that row.']};},
'heads':state=>({svg:wrap(box(10,180,210,100,'X\nT × 512',0,'data')+[65,220,375].map((y,i)=>box(370,y,420,85,`Head ${i+1} · Qᵢ, Kᵢ, Vᵢ\nT × 64`,i+1)+path(`M220,230 H290 V${y+42} H370`,i+1)).join('')+box(910,170,200,120,'Concatenate\nT × 512',4)+[107,262,417].map(y=>path(`M790,${y} H850 V230 H910`,4)).join('')+box(1190,170,185,120,'Wᴼ\nT × 512',5)+line(1110,230,1190,230,5)+A(6,text(690,505,'Original base Transformer: 8 heads × 64 dimensions = 512. Only 3 heads are drawn.','small'))),caps:['A multi-head sublayer starts from token vectors of width d_model.','Each head gets its own learned Q, K and V projections.','Another head can compute a different routing pattern.','Heads run in parallel; different specialisations are learned, not guaranteed.','Concatenate head outputs along the feature dimension.','The output projection mixes information across heads.','The sequence length stays T throughout this sublayer.']}),
'encoder-block':state=>({svg:wrap(box(60,405,360,70,'X: T × d_model',0,'data')+box(60,270,360,80,'Multi-head self-attention',1)+line(240,405,240,350,1)+box(60,150,360,70,'Add + LayerNorm',2)+line(240,270,240,220,2)+path('M60,440 H15 V185 H60',2)+box(790,270,420,80,'Feed-forward network',3)+path('M420,185 H680 V310 H790',3)+box(790,150,420,70,'Add + LayerNorm',4)+line(1000,270,1000,220,4)+path('M790,310 H740 V185 H790',4)+box(790,15,420,70,'Output: T × d_model',5,'data')+line(1000,150,1000,85,5)+A(5,text(680,510,'Original 2017 post-norm layout. Many later models use pre-norm.','small'))),caps:['Input is a sequence of vectors. A residual block preserves its outer shape.','Self-attention mixes information between positions.','Add the residual input, then normalise: LayerNorm(X + Attention(X)).','The feed-forward network transforms each position independently, with shared weights.','A second residual addition and normalisation complete the block.','Stack blocks to build increasingly contextual representations. This diagram follows the original paper’s post-norm order.']}),
'ffn':state=>({svg:wrap(box(20,190,250,90,'One token\n512 values',0,'data')+box(390,130,310,210,'Linear → ReLU\n2048 values',1)+line(270,235,390,235,1)+box(870,190,310,90,'Linear\n512 values',2)+line(700,235,870,235,2)+A(3,text(690,425,'The same network is applied independently at every position','bold'))+A(3,text(690,490,'FFN(x) = max(0, xW₁ + b₁)W₂ + b₂ · original base-model dimensions','small'))),caps:['Self-attention mixed positions. Now transform the features of each token.','Expand the feature width and apply a nonlinearity.','Project back to d_model so the residual addition is valid.','Feed-forward parameters are shared across positions; the tokens themselves do not mix in this sublayer.']}),
'transformer-map':state=>{let s=box(80,435,430,65,'Source token embeddings + positions',0,'data')+box(80,300,430,90,'Encoder self-attention',1)+line(295,435,295,390,1)+box(80,160,430,100,'Encoder FFN\nresiduals + normalisation',2)+line(295,300,295,260,2)+box(80,15,430,85,'Encoder memory H',3,'data')+line(295,160,295,100,3)+box(850,435,430,65,'Shifted target embeddings + positions',4,'data')+box(850,325,430,75,'Masked self-attention',5)+line(1065,435,1065,400,5)+box(850,205,430,75,'Cross-attention',6)+line(1065,325,1065,280,6)+path('M510,57 H680 V242 H850',6,'thick')+A(6,text(680,290,'K, V from encoder','small'))+box(850,100,430,65,'Decoder FFN',7)+line(1065,205,1065,165,7)+box(850,5,430,60,'Linear + vocabulary softmax',8,'dark')+line(1065,100,1065,65,8);return {svg:wrap(s),caps:['The source enters the encoder through embeddings plus position information.','Self-attention contextualises source tokens.','Each encoder block also contains an FFN, residual connections and normalisation.','All encoder outputs remain available as memory. The original base model stacks 6 encoder blocks.','The decoder receives the target prefix, shifted right during training.','Masked self-attention cannot access future target tokens.','Cross-attention takes decoder queries and encoder keys/values. It reads the source memory.','The decoder FFN follows cross-attention; each sublayer has its own residual and norm.','Vocabulary logits and softmax predict the next target token. The original base model stacks 6 decoder blocks.']};},
'cross-qkv':state=>({svg:wrap(box(35,70,470,95,'Encoder memory H\nT_source × d_model',0,'data')+box(35,350,470,95,'Decoder representations D\nT_target × d_model',0,'data')+box(690,55,285,75,'K = HWK',1)+box(1060,55,285,75,'V = HWV',1)+line(505,115,690,92,1)+path('M505,115 H570 V20 H1200 V55',1)+box(690,350,285,75,'Q = DWQ',2)+line(505,395,690,387,2)+box(890,205,455,90,'softmax(QKᵀ / √dₖ) V',3)+path('M830,350 V250 H890',3)+line(830,130,1000,205,3)+line(1200,130,1200,205,3)+A(4,text(690,510,'Attention matrix: T_target × T_source. Output length follows the decoder queries.','small bold'))),caps:['Cross-attention receives two different sequences.','The source memory supplies keys and values.','The target-side representation supplies queries.','Each target position reads a weighted mixture of source information.','Different source and target lengths fit naturally. Self-attention uses one sequence for Q, K and V; cross-attention uses two.']}),
'generation':state=>({svg:wrap(['<s>','the','cat','sat','</s>'].map((w,i)=>box(45+i*270,95,225,75,w,i,'data')).join('')+[0,1,2,3].map(i=>box(45+i*270,285,225,80,`Decode prefix\n${i+1} known token${i?'s':''}`,i+1)+line(157+i*270,170,157+i*270,285,i+1)+path(`M${157+i*270},365 V425 H${427+i*270} V170`,i+1)).join('')+A(5,text(690,495,'During generation, the next token is unknown until the current prediction is chosen.','small bold'))),caps:['Generation begins from a supplied prefix or start token.','Predict “the”, then append it. This is an illustrative sequence, not an actual pretrained-model output.','The longer prefix predicts “cat”.','Now predict “sat”.','An end token can stop generation. A maximum-length rule can also stop it.','Training can score all shifted targets in parallel; generating unknown future tokens remains sequential.']}),
};
Object.assign(SCENES,MORE_SCENES);
export function renderScene(name,state={}){if(!SCENES[name])throw Error('Unknown scene '+name);return SCENES[name](state);}
